import {publicContent,refreshPublicContent} from './public_content.js';
import {siteLang,tr,htmlText,uiText,setLanguage,applySiteLanguage,installLanguageObserver} from './web_i18n.js';
import {BUILD_ID,ASSET_VERSION} from './build_info.js';
import {partsAt,fromWall,shiftLocalDays,formatAt,setTimezoneRules} from './studio_time.js';
window.__MATHSTUDIO_SCRIPT_STARTED__ = true;
window.__MATHSTUDIO_BUILD__ = BUILD_ID;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Content boundaries must survive live DOM translation and background refreshes.
const content=value=>`<span data-no-translate>${esc(value)}</span>`;
let me=null,csrf='',settings={},posts=[],classes=[],schedule={lesson_types:[],availability:[],busy:[]};
let toastTimer,accountWatchTimer=null,accountWatchBusy=false,messageWatchTimer=null,globalRefreshTimer=null,globalRefreshBusy=false,globalRefreshSig='';
export function toast(text){uiText($('#toast'),text);$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6000);}
export async function api(path,data){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch(path,{method:data===undefined?'GET':'POST',signal:controller.signal,headers:data===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:data===undefined?undefined:JSON.stringify(data)});const j=await r.json();if(!r.ok){const ex=new Error(tr(j.error||'ui.request_failed'));ex.status=r.status;throw ex;}return j;}catch(ex){if(ex.name==='AbortError')throw new Error(tr("ui.the_server_took_too_long_to_respond_check_that_it_is_running"));throw ex;}finally{clearTimeout(timer);}}
const isAdmin=()=>me?.role==='admin';
function input(key,label,type='text',value='',extra=''){return `<label for="${key}">${htmlText(label)}</label><input id="${key}" name="${key}" type="${type}" value="${esc(value)}" ${extra}>`;}
function area(key,label,value='',max=2000){return `<label for="${key}">${htmlText(label)}</label><textarea id="${key}" name="${key}" maxlength="${max}" required>${esc(value)}</textarea>`;}
function values(form){return Object.fromEntries(new FormData(form));}
function formHandler(id,fn){const form=$(id);if(!form)return;form.addEventListener('submit',async ev=>{ev.preventDefault();const b=form.querySelector('button[type=submit],button:not([type])');if(b)b.disabled=true;const err=form.querySelector('.error');if(err)err.classList.add('hidden');try{await fn(values(form));}catch(ex){if(err){uiText(err,ex.message);err.classList.remove('hidden');}else toast(ex.message);}finally{if(b)b.disabled=false;}});}
const errors='<div class="error hidden" role="alert"></div>';
function date(ts,opts={}){return formatAt(ts*1000,studioZone(),siteLang==='zh'?'zh-CN':'en-CA',opts);}
const when=c=>date(c.start,{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})+' · '+tr('ui.duration',c.minutes);
const timeOnly=ts=>date(ts,{hour:'numeric',minute:'2-digit'});
const dayKey=ts=>date(ts,{year:'numeric',month:'2-digit',day:'2-digit'});
function studioZone(){return settings.timezone||'America/Edmonton';}
function studioMidnight(d){return fromWall({...partsAt(d,studioZone()),hour:0,minute:0,second:0},studioZone());}
function localDateTimeValue(d){
  return `${localDateValue(d)}T${quarterTimeValue(d)}`;
}
function ceilToQuarter(d){
  return new Date(Math.ceil(d.getTime()/900000)*900000);
}
function normalizeQuarterInput(el){
  if(!el?.value)return null;
  const [day,time]=el.value.split('T'),d=combineLocalDateTime(day,time);
  if(!d)return null;
  const snapped=ceilToQuarter(d);
  if(localDateTimeValue(snapped)!==el.value){
    el.value=localDateTimeValue(snapped);
    toast(tr("ui.time_adjusted_to_arg0_to_match_the_15_minute_calendar",timeOnly(snapped.getTime()/1000)));
  }
  return snapped;
}
function localDateValue(d){
  const p=partsAt(d,studioZone()),pad=n=>String(n).padStart(2,'0');
  return `${p.year}-${pad(p.month)}-${pad(p.day)}`;
}
function quarterTimeValue(d){const p=partsAt(d,studioZone());return `${String(p.hour).padStart(2,'0')}:${String(p.minute).padStart(2,'0')}`;}
function quarterTimeOptions(selected=''){
  let html='';
  for(let h=0;h<24;h++)for(const m of [0,15,30,45]){
    const value=`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`;
    const label=new Date(2000,0,1,h,m).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'});
    html+=`<option value="${value}" ${value===selected?'selected':''}>${esc(label)}</option>`;
  }
  return html;
}
function combineLocalDateTime(dateValue,timeValue){
  if(!/^\d{4}-\d{2}-\d{2}$/.test(dateValue)||!/^\d{2}:\d{2}$/.test(timeValue))return null;
  const [year,month,day]=dateValue.split('-').map(Number),[hour,minute]=timeValue.split(':').map(Number);
  return fromWall({year,month,day,hour,minute},studioZone());
}
function nav(){
  const path=location.pathname;
  const guest=me?.role==='guest';
  const accountLinks=me&&!guest?`<a href="/messages" ${path==='/messages'?'aria-current="page"':''} data-i18n="ui.messages">Messages</a><a href="/account" ${path==='/account'?'aria-current="page"':''} data-i18n="ui.my_lessons">My lessons</a><button id="logout" class="secondary small" data-i18n="ui.log_out">Log out</button>`:guest?`<span class="guest-chip" data-i18n="ui.guest">Guest</span><button id="logout" class="secondary small" data-i18n="ui.leave_guest_session">Leave guest session</button>`:"<a class=\"button small\" href=\"/login\" data-i18n=\"ui.log_in\">Log in</a>";
  $('#header').innerHTML=`<nav><a class="brand" href="/"><img src="/favicon.svg" alt="">${content(settings.name)}</a><div class="navlinks"><a href="/" ${path==='/'?'aria-current="page"':''} data-i18n="ui.home">Home</a><a href="/booking" ${path==='/booking'?'aria-current="page"':''} data-i18n="ui.book_a_lesson">Book a lesson</a><a href="/join" ${path==='/join'?'aria-current="page"':''} data-i18n="ui.join_meeting">Join meeting</a><a href="/resources" ${path==='/resources'?'aria-current="page"':''} data-i18n="ui.resources">Resources</a>${accountLinks}<button id="langToggle" class="secondary small" data-no-translate>${siteLang==='zh'?'EN':'中文'}</button></div></nav>`;
  $('#logout')?.addEventListener('click',async()=>{try{await api('/api/logout',{});location.href='/';}catch(ex){toast(ex.message);}});
  $('#langToggle')?.addEventListener('click',()=>{setLanguage(siteLang==='zh'?'en':'zh');nav();});
  $('#footer').innerHTML=`<span>${content(settings.name)} <span data-i18n="ui.thoughtful_mathematics_tutoring_built_around_the_student">· Thoughtful mathematics tutoring, built around the student.</span></span><span>${settings.contact?content(settings.contact):htmlText("ui.online_mathematics_tutoring")}</span>`;document.title=settings.name;
}

function formatBytes(bytes){const n=Number(bytes)||0;if(n<1024)return `${n} B`;if(n<1024*1024)return `${(n/1024).toFixed(n<10*1024?1:0)} KB`;if(n<1024*1024*1024)return `${(n/(1024*1024)).toFixed(n<10*1024*1024?1:0)} MB`;return `${(n/(1024*1024*1024)).toFixed(1)} GB`;}
function isIOSDevice(){return /iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);}
function resourceFileIcon(file){const name=(file.name||'').toLowerCase();if(file.mime==='application/pdf'||name.endsWith('.pdf'))return 'PDF';if((file.mime||'').startsWith('image/'))return 'IMG';if((file.mime||'').startsWith('video/'))return 'VID';if(/\.(doc|docx)$/.test(name))return 'DOC';if(/\.(ppt|pptx)$/.test(name))return 'PPT';if(/\.(xls|xlsx|csv)$/.test(name))return 'XLS';if(/\.zip$/.test(name))return 'ZIP';return 'FILE';}
function previewable(file){const m=file.mime||'',n=(file.name||'').toLowerCase();return m==='application/pdf'||m.startsWith('image/')||m.startsWith('video/')||m.startsWith('text/')||/\.(doc|docx|ppt|pptx|xls|xlsx)$/.test(n);}
function canTranslateFile(file){const n=(file.name||'').toLowerCase(),m=(file.mime||'').toLowerCase();return m.startsWith('text/')||m==='application/pdf'||/\.(txt|md|csv|json|html?|docx|pdf)$/.test(n);}
async function translateBundleFile(bundle,file,target,container){
  container.innerHTML="<div class=\"translation-loading\" data-i18n=\"ui.translating_document\">Translating document…</div>";
  try{
    const r=await api('/api/resources/translate',{grant:bundle.grant,file_id:file.id,target});
    container.innerHTML=`<div class="translation-head"><strong>${htmlText('ui.translated_reading_view')}</strong><span>${target==='zh-CN'?'中文':'English'} · ${content(file.name)}</span></div><div class="translation-text" data-no-translate>${esc(r.text).replace(/\n/g,'<br>')}</div>`;
    applySiteLanguage(container);
  }catch(ex){container.innerHTML=`<div class="notice translation-error">${esc(ex.message)}</div>`;}
}
function renderResourceBundle(bundle){
  const box=$('#resourceResult');if(!box)return;const ios=isIOSDevice();const grant=encodeURIComponent(bundle.grant);const primary=bundle.files.length>1?`<a class="button" href="/resource/download-all?grant=${grant}"><span data-i18n="ui.download_all">Download all (</span>${bundle.files.length}<span data-i18n="ui.as_zip">) as ZIP</span></a>`:`<a class="button" href="/resource/download?grant=${grant}&file=${bundle.files[0].id}" data-i18n="ui.download_file">Download file</a>`;
  const translation=bundle.translate_enabled?`<section class="translation-panel"><div class="translation-panel-head"><div><p class="eyebrow" data-i18n="ui.automatic_translation">Automatic translation</p><h3>${htmlText('ui.document_translation_is_enabled_for_this_share_code')}</h3><p class="muted">${htmlText('ui.supports_text_docx_and_text_based_pdfs_document_text_is_sent_to_an_online_translation_serv')}</p></div><select id="translationTarget" aria-label="Translation language" data-i18n-aria-label="ui.translation_language"><option value="en" ${siteLang==='en'?'selected':''} data-i18n="ui.english">English</option><option value="zh-CN" ${siteLang==='zh'?'selected':''}>中文</option></select></div><div id="translationResults" class="translation-results"></div></section>`:'';
  box.innerHTML=`<div class="resource-success"><div><p class="eyebrow" data-i18n="ui.access_code_accepted">Access code accepted</p><h2>${content(bundle.label)}</h2><p class="muted">${bundle.files.length} <span data-i18n="ui.file">file</span>${bundle.files.length===1?'':'s'} <span data-i18n="ui.ready_download_links_remain_available_for_30_minutes_on_this_device">ready. Download links remain available for 30 minutes on this device.</span></p></div>${primary}</div>${ios?`<div class="ios-help"><strong data-i18n="ui.iphone_ipad">iPhone / iPad</strong><p><span data-i18n="ui.for_pdfs_and_images">For PDFs and images,</span> <b data-i18n="ui.open">Open</b> <span data-i18n="ui.lets_you_preview_the_file_in_safari_then_use_share_save_to_files_for_several_files">lets you preview the file in Safari, then use Share → Save to Files. For several files,</span> <b data-i18n="ui.download_all_2">Download all</b> <span data-i18n="ui.saves_one_zip_in_the_files_app_s_downloads_folder">saves one ZIP in the Files app’s Downloads folder.</span></p></div>`:''}<div class="resource-download-list">${bundle.files.map(f=>`<article class="resource-download-row"><span class="file-kind">${resourceFileIcon(f)}</span><div><strong>${content(f.name)}</strong><span>${formatBytes(f.size)}</span></div><div class="actions">${previewable(f)?`<a class="button secondary small" target="_blank" rel="noopener" href="/resource/open?grant=${grant}&file=${f.id}" data-i18n="ui.open">Open</a>`:''}<a class="button small" href="/resource/download?grant=${grant}&file=${f.id}" data-i18n="ui.download">Download</a></div></article>`).join('')}</div>${translation}`;
  box.scrollIntoView({behavior:'smooth',block:'nearest'});applySiteLanguage(box);
  if(bundle.translate_enabled){
    const results=$('#translationResults'),select=$('#translationTarget');
    const run=()=>{results.innerHTML='';for(const f of bundle.files.filter(canTranslateFile)){const card=document.createElement('article');card.className='translation-card';results.appendChild(card);translateBundleFile(bundle,f,select.value,card);}if(!results.children.length)results.innerHTML="<div class=\"notice\" data-i18n=\"ui.no_text_based_files_in_this_bundle_can_be_translated_automatically\">No text-based files in this bundle can be translated automatically.</div>";};
    select.addEventListener('change',run);run();
  }
}

async function instantJoin(){
  stopAccountWatcher();
  const qs=new URLSearchParams(location.search), preset=(qs.get('code')||'').replace(/\D/g,'').slice(0,10);
  const guest=!me||me.role==='guest';
  $('#app').innerHTML=`<div class="join-meeting-shell"><section class="join-meeting-card"><div class="join-meeting-mark">10</div><p class="eyebrow">${htmlText("ui.instant_classroom")}</p><h1>${htmlText("ui.join_a_meeting")}</h1><p class="muted">${htmlText("ui.enter_the_10_digit_code_from_your_teacher_you_can_join_with_your_mathstudio_account_or_con")}</p><form id="instantJoinForm">${errors}<label for="meeting_code">${htmlText("ui.meeting_code")}</label><input id="meeting_code" name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="10" pattern="[0-9]{10}" placeholder="1234567890" value="${esc(preset)}" required>${guest?`<label for="guest_name">${htmlText("ui.your_name")}</label><input id="guest_name" name="name" maxlength="80" autocomplete="name" placeholder="${tr("ui.name_shown_in_the_meeting")}" data-i18n-placeholder="ui.name_shown_in_the_meeting" required>`:`<div class="signed-in-join"><span>${htmlText("ui.joining_as")}</span><strong>${content(me.name)}</strong></div>`}<button type="submit">${htmlText("ui.join_meeting")}</button></form>${!guest?`<p class="meta">${htmlText("ui.you_are_signed_in_your_account_name_will_be_used_in_the_meeting")}</p>`:`<p class="meta">${htmlText("ui.guest_access_does_not_require_creating_an_account")}</p>`}</section></div>`;
  const code=$('#meeting_code');code?.focus();code?.addEventListener('input',()=>{code.value=code.value.replace(/\D/g,'').slice(0,10);});
  formHandler('#instantJoinForm',async d=>{
    const payload={code:String(d.code||'').replace(/\D/g,'')};
    if(guest)payload.name=String(d.name||'').trim();
    const r=await api('/api/instant/join',payload);
    location.href=`/classroom?id=${encodeURIComponent(r.class_id)}&instant=1`;
  });
}

async function resources(){
  stopAccountWatcher();
  const linkedCode=(new URLSearchParams(location.search).get('code')||'').trim();
  $('#app').innerHTML=`<div class="pagehead resource-head"><div><p class="eyebrow" data-i18n="ui.class_resources_2">Class resources</p><h1 data-i18n="ui.download_your_files">Download your files</h1><p class="muted" data-i18n="ui.enter_the_access_code_your_teacher_gave_you_or_open_a_resource_code_directly_from_classroo">Enter the access code your teacher gave you, or open a resource code directly from classroom chat.</p></div></div><section class="resource-code-panel"><form id="resourceCodeForm">${errors}<label for="resource_code" data-i18n="ui.access_code">Access code</label><div class="resource-code-entry"><input id="resource_code" name="code" autocomplete="off" autocapitalize="characters" spellcheck="false" maxlength="20" placeholder="Example: 7K4M9Q" required data-i18n-placeholder="ui.example_7k4m9q"><button data-i18n="ui.get_files">Get files</button></div><p class="field-help" data-i18n="ui.codes_are_not_case_sensitive_spaces_or_hyphens_are_ignored_the_code_box_stays_available_ev">Codes are not case-sensitive. Spaces or hyphens are ignored. The code box stays available even if you arrived from classroom chat.</p></form></section><section id="resourceResult" class="section resource-result"><div class="empty"><h3 data-i18n="ui.notes_homework_and_class_files">Notes, homework, and class files</h3><p data-i18n="ui.your_teacher_can_bundle_several_files_under_one_code_so_one_code_can_download_an_entire_un">Your teacher can bundle several files under one code, so one code can download an entire unit’s materials.</p></div></section>`;
  const redeem=async code=>{const r=await api('/api/resources/redeem',{code});renderResourceBundle(r);};
  formHandler('#resourceCodeForm',async d=>redeem(d.code));
  const input=$('#resource_code');
  if(linkedCode){input.value=linkedCode;try{await redeem(linkedCode);history.replaceState(null,'','/resources');}catch(ex){const err=$('#resourceCodeForm .error');if(err){uiText(err,ex.message);err.classList.remove('hidden');}toast(ex.message);input.focus();}}
  else input?.focus();
}
async function uploadTeacherFile(file){const r=await fetch('/api/admin/files/upload',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-CSRF-Token':csrf,'X-File-Name':encodeURIComponent(file.name),'X-File-Type':encodeURIComponent(file.type||'')},body:file});let j={};try{j=await r.json();}catch{}if(!r.ok)throw new Error(j.error||`Could not upload ${file.name}.`);return j;}
