function auth(signup=false){
  const title=signup?tr("ui.create_account"):tr("ui.log_in");
  const eyebrow=signup?tr("ui.student_account"):tr("ui.welcome_back");
  const below=signup
    ? `${htmlText("ui.already_have_an_account")} <a href="/login">${htmlText("ui.log_in")}</a>`
    : `${htmlText("ui.new_here")} <a href="/signup">${htmlText("ui.create_account")}</a>`;
  const help=signup?tr("ui.use_a_unique_password_with_at_least_12_characters"):tr("ui.forgot_your_password_contact_your_teacher_for_a_reset");
  $('#app').innerHTML=`<section class="auth panel"><p class="eyebrow">${htmlText(eyebrow)}</p><h1>${htmlText(title)}</h1><form id="auth">${errors}${signup?input('name',"ui.name",'text','','required maxlength="80" autocomplete="name"'):''}${input('username',"ui.username",'text','','required minlength="3" maxlength="40" autocomplete="username" pattern="[a-zA-Z0-9_]+"')}${input('password',"ui.password",'password','',`required ${signup?'minlength="12"':''} maxlength="256" autocomplete="${signup?'new':'current'}-password"`)}${signup?input('confirm',"ui.confirm_password",'password','','required minlength="12" autocomplete="new-password"'):''}<button>${htmlText(title)}</button></form><p>${below}</p><p class="meta">${htmlText(help)}</p></section>`;
  formHandler('#auth',async d=>{if(signup&&d.password!==d.confirm)throw new Error(tr('ui.passwords_do_not_match'));const r=await api(signup?'/api/signup':'/api/login',d);csrf=r.csrf;me=r.user;const next=new URLSearchParams(location.search).get('next');location.href=['/booking','/teacher/translations'].includes(next)?next:'/account';});
}

function groupLessonCard(c){
  const left=Math.max(0,(c.capacity||0)-(c.booked||0));
  const full=left<=0;
  const mine=!!c.mine;
  const chat=mine&&c.group_chat_id?`<a class="button secondary small" href="/messages?group=${c.group_chat_id}" data-i18n="ui.group_chat">Group chat</a>`:'';
  let action='';
  if(mine)action=`<span class="tag" data-i18n="ui.seat_reserved">Seat reserved</span>${chat}${c.start>Date.now()/1000?`<button class="secondary small" data-unbook="${c.id}" data-i18n="ui.cancel_seat">Cancel seat</button>`:''}`;
  else if(!me)action=`<a class="button small" href="/login?next=/booking" data-i18n="ui.log_in_to_book">Log in to book</a>`;
  else action=`<button class="small" data-groupjoin="${c.id}" ${full?'disabled':''}>${full?htmlText('ui.full'):htmlText("ui.reserve_a_seat")}</button>`;
  return `<article class="group-lesson-card"><div class="group-lesson-main"><div class="group-lesson-badges"><span class="tag" data-i18n="ui.group_lesson">Group lesson</span><span class="tag gray">${c.booked||0}/${c.capacity} <span data-i18n="ui.seats">seats</span></span>${c.price_label?`<span class="tag gray">${content(c.price_label)}</span>`:''}</div><h3>${content(c.title)}</h3><p class="meta">${esc(when(c))}</p><p>${c.description?(c.class_kind==='group'?publicContent('groups',c.id,'description',c.description):content(c.description)):htmlText("ui.small_group_mathematics_lesson")}</p><div class="seat-meter" aria-label="${esc(tr('ui.seats_remaining',left))}" data-i18n-aria-label="ui.seats_remaining" data-i18n-args="${esc(JSON.stringify([left]))}"><span style="width:${Math.min(100,Math.round(((c.booked||0)/(c.capacity||1))*100))}%"></span></div><small>${full?htmlText("ui.no_seats_remaining"):htmlText('ui.seats_remaining',left)}</small></div><div class="actions">${action}</div></article>`;
}
function classCard(c,admin=false){
  const now=Date.now()/1000,future=c.start>now,scheduledTimePassed=c.start<=now,scheduledEndPassed=c.start+c.minutes*60<=now;
  const approval=c.approval||'confirmed';let actions='';
  const messageLink=approval==='confirmed'&&c.status!=='cancelled'?(c.class_kind==='group'&&c.group_chat_id?`<a class="button secondary small" href="/messages?group=${c.group_chat_id}" data-i18n="ui.group_chat">Group chat</a>`:`<a class="button secondary small" href="/messages?id=${c.id}" data-i18n="ui.messages">Messages</a>`):'';
  if(admin){
    if(c.status==='scheduled'&&approval==='confirmed'){
      const tooEarly=now<c.start-1800;
      const openLabel=scheduledTimePassed?tr("ui.start_late_in_teacher_app"):tr("ui.start_teacher_app");
      actions=`${messageLink}${!c.live?`<button class="small" data-teacherlaunch="${c.id}" ${tooEarly?'disabled':''}>${openLabel}</button>`:`<button class="small" data-teacherlaunch="${c.id}" data-i18n="ui.open_teacher_app">Open teacher app</button><button class="small secondary" data-classaction="end" data-id="${c.id}" data-i18n="ui.end_class">End class</button>`}<button class="small secondary" data-classaction="cancel" data-id="${c.id}" data-i18n="ui.cancel">Cancel</button>`;
    }else actions=messageLink;
  }else if(c.mine&&c.status==='scheduled'){
    const waitingLate=approval==='confirmed'&&!c.live&&scheduledTimePassed;
    actions=`${approval==='pending'?"<span class=\"tag orange\" data-i18n=\"ui.waiting_for_teacher\">Waiting for teacher</span>":waitingLate?"<span class=\"tag orange\" data-i18n=\"ui.waiting_for_teacher_to_start\">Waiting for teacher to start</span>":"<span class=\"tag\" data-i18n=\"ui.confirmed\">Confirmed</span>"}${approval==='confirmed'?messageLink:''}${approval==='confirmed'&&c.live?`<a class="button small" href="/classroom?id=${c.id}" data-i18n="ui.join_classroom">Join classroom</a>`:''}${future?`<button class="secondary small" data-unbook="${c.id}">${c.class_kind==='group'?htmlText("ui.cancel_seat"):htmlText("ui.cancel_booking")}</button>`:''}`;
  }
  const groupTag=c.class_kind==='group'?`<span class="tag orange"><span data-i18n="ui.group">Group ·</span> ${c.booked||0}/${c.capacity}</span>`:'';
  const timingTag=c.status==='scheduled'&&approval==='confirmed'&&!c.live&&scheduledEndPassed?"<span class=\"tag orange\" data-i18n=\"ui.scheduled_time_passed\">Scheduled time passed</span>":'';
  return `<article class="card class-row"><div class="datebox">${date(c.start,{month:'short'})}<strong>${date(c.start,{day:'numeric'})}</strong>${date(c.start,{weekday:'short'})}</div><div><span class="tag">${esc(c.minutes)} <span data-i18n="ui.min">min</span></span> ${groupTag} ${c.price_label?`<span class="tag gray">${content(c.price_label)}</span>`:''} ${c.status!=='scheduled'?`<span class="tag gray">${esc(c.status)}</span>`:approval==='pending'?"<span class=\"tag orange\" data-i18n=\"ui.pending\">Pending</span>":c.live?"<span class=\"tag orange\" data-i18n=\"ui.classroom_open\">Classroom open</span>":timingTag}<h3>${content(c.title)}</h3><p class="meta">${esc(when(c))}</p></div><div class="actions">${actions}</div></article>`;
}
async function refreshClasses(){classes=(await api('/api/classes')).classes;}
async function refreshSchedule(){schedule=await api('/api/schedule');}
function weekStartFromParam(){const q=new URLSearchParams(location.search).get('week');let d=q?new Date(+q*1000):new Date();if(Number.isNaN(d.getTime()))d=new Date();const p=partsAt(d,studioZone()),day=new Date(Date.UTC(p.year,p.month-1,p.day)).getUTCDay();return shiftLocalDays(studioMidnight(d),-((day+6)%7),studioZone());}
function shiftWeek(start,delta){return Math.floor(shiftLocalDays(start,delta*7,studioZone()).getTime()/1000);}
function weekKeys(start){return Array.from({length:7},(_,i)=>dayKey(shiftLocalDays(start,i,studioZone()).getTime()/1000));}
function slotFits(start,minutes){const end=start+minutes*60;return !schedule.busy.some(b=>b.status==='scheduled'&&b.start<end&&b.start+b.minutes*60>start);}
function slotsFor(a,lesson){const out=[];const first=Math.ceil(a.start/(15*60))*(15*60);for(let st=first;st+lesson.minutes*60<=a.end+0.001;st+=15*60){if(st>Date.now()/1000+30&&slotFits(st,lesson.minutes))out.push(st);}return out;}
function lessonLabel(l){return `${l.name} — ${tr('ui.duration',l.minutes)}`;}
function minuteOfDay(ts){const p=partsAt(ts*1000,studioZone());return p.hour*60+p.minute;}
function gridTimestamp(start,dayIndex,minute){const day=partsAt(shiftLocalDays(start,dayIndex,studioZone()),studioZone());const d=fromWall({...day,hour:Math.floor(minute/60),minute:minute%60,second:0},studioZone());return d?Math.floor(d.getTime()/1000):null;}
function calendarBounds(start,adminBookings=[]){const keys=weekKeys(start);let low=8*60,high=22*60;const points=[];for(const a of schedule.availability){if(keys.includes(dayKey(a.start))){points.push(minuteOfDay(a.start),minuteOfDay(a.end));}}const source=adminBookings.length?adminBookings:schedule.busy;for(const b of source){if(b.status==='scheduled'&&keys.includes(dayKey(b.start))){points.push(minuteOfDay(b.start),minuteOfDay(b.start+b.minutes*60));}}if(points.length){low=Math.min(low,Math.floor((Math.min(...points)-30)/60)*60);high=Math.max(high,Math.ceil((Math.max(...points)+30)/60)*60);}return [Math.max(0,low),Math.min(24*60,high)];}
function sameCalendarDay(tsA,tsB){return dayKey(tsA)===dayKey(tsB);}
function calendarLegendHTML(admin=false){return `<div class="calendar-legend">${admin?"<span><i class=\"legend-swatch open\"></i><span data-i18n=\"ui.teacher_available\">Teacher available</span></span><span><i class=\"legend-swatch confirmed\"></i><span data-i18n=\"ui.confirmed_lesson\">Confirmed lesson</span></span><span><i class=\"legend-swatch pending\"></i><span data-i18n=\"ui.pending_request\">Pending request</span></span>":"<span><i class=\"legend-swatch available\"></i><span data-i18n=\"ui.available_start\">Available start</span></span><span><i class=\"legend-swatch open\"></i><span data-i18n=\"ui.teacher_available\">Teacher available</span></span><span><i class=\"legend-swatch blocked\"></i><span data-i18n=\"ui.unavailable\">Unavailable</span></span>"}</div>`;}
function availabilityManagerHTML(start){const keys=weekKeys(start);const list=schedule.availability.filter(a=>keys.includes(dayKey(a.start))).sort((a,b)=>a.start-b.start);if(!list.length)return "<div class=\"availability-manager empty-compact\" data-i18n=\"ui.no_availability_has_been_added_for_this_week\">No availability has been added for this week.</div>";return `<div class="availability-manager"><div class="availability-manager-head"><strong data-i18n="ui.availability_this_week">Availability this week</strong><span>${list.length} <span data-i18n="ui.block">block</span>${list.length===1?'':'s'}</span></div>${list.map(a=>`<div class="availability-manager-row"><div><strong>${date(a.start,{weekday:'short',month:'short',day:'numeric'})}</strong><span>${timeOnly(a.start)}–${timeOnly(a.end)}</span></div><button class="secondary small" data-closeavail="${a.id}" data-i18n="ui.close_availability">Close availability</button></div>`).join('')}</div>`;}
function scheduleWeekHTML(start,lesson,admin=false,adminBookings=[]){const [fromMinute,toMinute]=calendarBounds(start,adminBookings);const rows=[];for(let minute=fromMinute;minute<toMinute;minute+=15){const sample=gridTimestamp(start,0,minute);rows.push(`<div class="calendar-time ${minute%60===0?'hour':''}">${timeOnly(sample)}</div>`);for(let dayIndex=0;dayIndex<7;dayIndex++){const ts=gridTimestamp(start,dayIndex,minute);if(ts===null){rows.push('<div class="calendar-cell blocked"></div>');continue;}const cellEnd=ts+15*60;if(admin){const booking=adminBookings.find(b=>b.status==='scheduled'&&b.start<cellEnd&&b.start+b.minutes*60>ts);const av=schedule.availability.find(a=>a.start<cellEnd&&a.end>ts);if(booking){const first=booking.start>=ts&&booking.start<cellEnd;const status=booking.approval==='pending'?'pending':'confirmed';const names=(booking.attendees||[]).map(x=>x.name).filter(Boolean);const who=names.length?names.join(', '):(booking.name||((booking.class_kind==='group')?tr("ui.no_seats_reserved"):tr("ui.student")));const groupInfo=booking.class_kind==='group'?`${booking.booked||names.length}/${booking.capacity||'?'} seats · ${who}`:who;rows.push(`<div class="calendar-cell booking ${status}" data-no-translate title="${esc(booking.title)} · ${esc(groupInfo)} · ${timeOnly(booking.start)}–${timeOnly(booking.start+booking.minutes*60)}">${first?`<span class="calendar-cell-label"><strong>${content(groupInfo)}</strong><small>${content(booking.title)} · ${timeOnly(booking.start)}</small></span>`:''}</div>`);}else if(av){const first=av.start>=ts&&av.start<cellEnd;rows.push(`<div class="calendar-cell teacher-open" title="Teacher available ${timeOnly(av.start)}–${timeOnly(av.end)}">${first?"<span class=\"calendar-cell-label subtle\" data-i18n=\"ui.available\">Available</span>":''}</div>`);}else rows.push('<div class="calendar-cell"></div>');}else{const availability=schedule.availability.find(a=>a.start<=ts&&a.end>=cellEnd);const occupied=schedule.busy.find(b=>b.status==='scheduled'&&b.start<cellEnd&&b.start+b.minutes*60>ts);const canStart=availability&&ts+lesson.minutes*60<=availability.end+0.001&&ts>Date.now()/1000+30&&slotFits(ts,lesson.minutes);if(canStart){const label=`${date(ts,{weekday:'long',month:'short',day:'numeric'})}, ${timeOnly(ts)}–${timeOnly(ts+lesson.minutes*60)}`;rows.push(`<button type="button" class="calendar-cell slot-cell" data-requestslot="${ts}" data-availability="${availability.id}" aria-label="Book ${esc(lesson.name)} on ${esc(label)}" title="Book ${esc(label)}"><span class="slot-plus" aria-hidden="true">+</span></button>`);}else if(occupied){rows.push("<div class=\"calendar-cell blocked\" title=\"Unavailable\" data-i18n-title=\"ui.unavailable\"></div>");}else if(availability){rows.push("<div class=\"calendar-cell teacher-open student-open\" title=\"Teacher is available, but the selected lesson cannot start here.\" data-i18n-title=\"ui.teacher_is_available_but_the_selected_lesson_cannot_start_here\"></div>");}else rows.push('<div class="calendar-cell"></div>');}}}
const headers=[];const now=Math.floor(Date.now()/1000);for(let i=0;i<7;i++){const d=shiftLocalDays(start,i,studioZone());const ts=Math.floor(d.getTime()/1000);headers.push(`<div class="calendar-day ${sameCalendarDay(ts,now)?'today':''}"><span>${date(ts,{weekday:'short'})}</span><strong>${date(ts,{day:'numeric'})}</strong><small>${date(ts,{month:'short'})}</small></div>`);}return `<div class="weekly-calendar ${admin?'admin-calendar':''}"><div class="calendar-grid"><div class="calendar-corner" data-i18n="ui.time">Time</div>${headers.join('')}${rows.join('')}</div></div>`;}
function dayHeading(ts){const now=Date.now()/1000,today=dayKey(now),tomorrow=dayKey(shiftLocalDays(studioMidnight(new Date()),1,studioZone()).getTime()/1000),yesterday=dayKey(shiftLocalDays(studioMidnight(new Date()),-1,studioZone()).getTime()/1000),key=dayKey(ts);if(key===today)return tr('ui.today_date',date(ts,{weekday:'long',month:'short',day:'numeric'}));if(key===tomorrow)return tr('ui.tomorrow_date',date(ts,{weekday:'long',month:'short',day:'numeric'}));if(key===yesterday)return tr('ui.yesterday_date',date(ts,{weekday:'long',month:'short',day:'numeric'}));return date(ts,{weekday:'long',month:'short',day:'numeric',year:'numeric'});}
function byDayHTML(list,renderer){const groups=[];for(const item of [...list].sort((a,b)=>a.start-b.start)){const key=dayKey(item.start);let group=groups.at(-1);if(!group||group.key!==key){group={key,start:item.start,items:[]};groups.push(group);}group.items.push(item);}return groups.map(g=>`<section class="class-day-group"><div class="class-day-heading"><span>${esc(dayHeading(g.start))}</span><small>${htmlText('ui.class_count',g.items.length)}</small></div><div class="class-day-items">${g.items.map(renderer).join('')}</div></section>`).join('');}

function classWatchSignature(list){return JSON.stringify(list.filter(c=>c.mine).map(c=>[c.id,c.live,c.status,c.approval,c.start,c.minutes]));}
function stopAccountWatcher(){
  if(accountWatchTimer!==null){clearInterval(accountWatchTimer);accountWatchTimer=null;}
  accountWatchBusy=false;
}
function startAccountWatcher(){
  clearInterval(accountWatchTimer);
  let signature=classWatchSignature(classes);
  const check=async()=>{
    if(accountWatchBusy||document.hidden||location.pathname!=='/account')return;
    accountWatchBusy=true;
    try{
      const next=(await api('/api/classes')).classes;
      const nextSignature=classWatchSignature(next);
      if(nextSignature!==signature){classes=next;signature=nextSignature;await booking(true);}
    }catch{}finally{accountWatchBusy=false;}
  };
  accountWatchTimer=setInterval(check,2000);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)check();},{once:true});
}
