  if(!lesson){$('#app').innerHTML=`<div class="pagehead"><div><h1 data-i18n="ui.book_a_lesson">Book a lesson</h1></div></div>${groupSection}`;bindClassActions(()=>booking(false));return;}
  $('#app').innerHTML=`<div class="pagehead booking-head"><div><p class="eyebrow" data-i18n="ui.book_a_lesson">Book a lesson</p><h1 data-i18n="ui.choose_private_or_small_group_learning">Choose private or small-group learning.</h1><p class="muted" data-i18n="ui.reserve_a_seat_in_a_posted_group_lesson_or_choose_a_private_lesson_and_select_an_available">Reserve a seat in a posted group lesson, or choose a private lesson and select an available start time.</p></div>${me?"<a class=\"button secondary\" href=\"/account\" data-i18n=\"ui.my_lessons\">My lessons</a>":"<a class=\"button\" href=\"/login?next=/booking\" data-i18n=\"ui.log_in_to_book\">Log in to book</a>"}</div>${groupSection}<section class="section private-booking"><div class="sectionhead"><div><p class="eyebrow" data-i18n="ui.private_lessons">Private lessons</p><h2 data-i18n="ui.book_one_to_one_time">Book one-to-one time</h2></div></div><div class="course-description">${publicContent('courses',lesson.id,'description',lesson.description||'')}</div><section class="booking-picker panel"><div><label for="lessonChoice" data-i18n="ui.lesson">Lesson</label><select id="lessonChoice">${schedule.lesson_types.map(l=>`<option data-no-translate value="${l.id}" ${l.id===lesson.id?'selected':''}>${esc(lessonLabel(l))}</option>`).join('')}</select><p class="field-help" data-i18n="ui.available_starts_update_automatically_for_the_selected_duration">Available starts update automatically for the selected duration.</p></div><div class="price-box"><span data-i18n="ui.lesson_price">Lesson price</span><strong>${content(lesson.price_label)}</strong><small data-i18n="ui.final_pricing_will_be_confirmed_by_the_teacher">Final pricing will be confirmed by the teacher.</small></div></section><div class="week-toolbar"><a class="button secondary small" href="/booking?lesson=${lesson.id}&week=${shiftWeek(start,-1)}" data-i18n="ui.previous_week_2">← Previous week</a><div><span class="toolbar-kicker" data-i18n="ui.weekly_availability">Weekly availability</span><h2>${date(start.getTime()/1000,{month:'short',day:'numeric'})} – ${date(shiftLocalDays(start,6,studioZone()).getTime()/1000,{month:'short',day:'numeric',year:'numeric'})}</h2></div><a class="button secondary small" href="/booking?lesson=${lesson.id}&week=${shiftWeek(start,1)}" data-i18n="ui.next_week_2">Next week →</a></div>${calendarLegendHTML(false)}<div class="calendar-note"><strong>${content(lesson.name)}</strong><span>${lesson.minutes} <span data-i18n="ui.minutes">minutes</span></span><span><span data-i18n="ui.times_are_shown_in">Times are shown in</span> ${esc(settings.timezone||tr("ui.the_studio_timezone"))}</span></div>${scheduleWeekHTML(start,lesson)}<p class="calendar-help"><span data-i18n="ui.the_calendar_is_divided_into_15_minute_intervals_green">The calendar is divided into 15-minute intervals. Green</span> <strong>+</strong> <span data-i18n="ui.cells_are_valid_start_times_for_your_selected_lesson_a_requested_time_is_held_while_the_te">cells are valid start times for your selected lesson. A requested time is held while the teacher reviews it.</span></p></section>`;
  $('#lessonChoice').onchange=e=>{const q=new URLSearchParams(location.search);q.set('lesson',e.target.value);location.href='/booking?'+q.toString();};
