  const groupRepeat=$('#group_repeat_weekly'),groupRepeatWrap=$('#groupRepeatWeeksWrap');groupRepeat.onchange=()=>groupRepeatWrap.classList.toggle('hidden',!groupRepeat.checked);const groupStart=ceilToQuarter(new Date(Date.now()+60*60*1000));$('#group_lesson_date').value=localDateValue(groupStart);$('#group_lesson_time').value=quarterTimeValue(groupStart);
  formHandler('#groupLessonForm',async d=>{const st=combineLocalDateTime(d.date,d.time);if(!st)throw new Error(tr("ui.choose_a_valid_group_lesson_date_and_time"));const r=await api('/api/admin/group-class',{title:d.group_lesson_title,lesson_type_id:+d.lesson_type_id,start:st.getTime()/1000,capacity:+d.capacity,price_label:d.group_price_label,description:d.description,repeat_weekly:groupRepeat.checked,weeks:groupRepeat.checked?(+d.group_weeks||6):1});toast(tr("ui.posted_arg0_group_lessonarg1_and_created_its_group_chat",r.created,r.created===1?'':'s'));await admin();});
  $('#createGroupForm')?.addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.currentTarget,button=form.querySelector('button'),name=$('#group_name').value.trim();const user_ids=[...form.querySelectorAll('input[name="new_group_member"]:checked')].map(x=>+x.value);button.disabled=true;try{await api('/api/admin/groups/create',{name,user_ids});toast(tr("ui.group_chat_created"));await admin();}catch(ex){form.querySelector('.error').textContent=ex.message;form.querySelector('.error').classList.remove('hidden');button.disabled=false;}});
