function pageRefreshSignature(){
  return JSON.stringify({
    timezone:settings.timezone,
    classes:classes.map(c=>[c.id,c.status,c.live,c.approval,c.start,c.minutes,c.booked,c.capacity,c.share_code||'']),
    availability:(schedule.availability||[]).map(a=>[a.id,a.start,a.end,a.status]),
    busy:(schedule.busy||[]).map(b=>[b.id,b.start,b.minutes,b.status,b.approval]),
    posts:(posts||[]).map(p=>[p.id,p.title,p.created])
  });
}
function userIsEditing(){
  const el=document.activeElement;
  return !!el&&['INPUT','TEXTAREA','SELECT'].includes(el.tagName)&&!el.disabled;
}
async function autoRefreshCurrentPage(){
  if(globalRefreshBusy||document.hidden||location.pathname==='/classroom'||location.pathname==='/login'||location.pathname==='/signup')return;
  globalRefreshBusy=true;
  try{
    const path=location.pathname;
    if(path==='/'||path==='/booking'||path==='/account'){
      const [nextClasses,nextSchedule,pub]=await Promise.all([api('/api/classes'),api('/api/schedule'),api('/api/public')]);
      classes=nextClasses.classes;schedule=nextSchedule;settings=pub.settings;setTimezoneRules(pub.timezone_rules);posts=pub.posts;await refreshPublicContent(api,pub);
      const sig=pageRefreshSignature();
      if(sig!==globalRefreshSig&&!userIsEditing()){
        globalRefreshSig=sig;
        if(path==='/')home();
        else if(path==='/booking')await booking(false);
        else if(path==='/account')await booking(true);
      }
    }
    // Keep resource grants, downloads, inputs and translation DOM intact.
    // Every resource operation still checks expiry/revocation on the server.
    nav();
  }catch{}finally{globalRefreshBusy=false;}
}
function startGlobalAutoRefresh(){
  if(globalRefreshTimer)clearInterval(globalRefreshTimer);
  globalRefreshSig=pageRefreshSignature();
  globalRefreshTimer=setInterval(autoRefreshCurrentPage,3000);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)autoRefreshCurrentPage();});
}
async function boot(){try{const r=await api('/api/me');me=r.user;csrf=r.csrf;const pub=await api('/api/public');settings=pub.settings;setTimezoneRules(pub.timezone_rules);posts=pub.posts;await refreshPublicContent(api,pub);nav();await refreshClasses();switch(location.pathname){case '/teacher/translations':{const {mountTranslationManager}=await import('./translation_manager.js');await mountTranslationManager({api,me,esc,toast});break;}case '/login':auth();break;case '/signup':auth(true);break;case '/booking':await booking();break;case '/account':await booking(true);break;case '/join':await instantJoin();break;case '/resources':await resources();break;case '/messages':if(me?.role==='guest'){location.href='/join';return;}await messagesPage();break;case '/classroom':if(!me){location.href='/join';return;}const {mountClassroom}=await import(`./classroom.js?v=${ASSET_VERSION}`);await mountClassroom({api,toast,me,settings,classes,esc,tr,localize:applySiteLanguage});break;default:home();}startGlobalAutoRefresh();window.__MATHSTUDIO_BOOTED__=true;}catch(ex){window.__MATHSTUDIO_BOOT_ERROR__=String(ex?.stack||ex);$('#app').innerHTML=`<div class="error"><strong data-i18n="ui.math_studio_could_not_start">Math Studio could not start.</strong><br>${esc(ex.message)}</div><p class="meta"><span data-i18n="ui.build">Build</span> ${BUILD_ID}</p><a href="/" data-i18n="ui.try_again">Try again</a>`;}}
window.addEventListener('mathstudio-language',async()=>{const path=location.pathname;if(path==='/')home();else if(path==='/booking'||path==='/account')await booking(path==='/account');applySiteLanguage();});
installLanguageObserver();
boot();
